<template>
  <div class="app-shell">
    <aside class="sidebar" :class="{ collapsed }">
      <div class="brand"><div class="brand-mark"><span>蓉</span></div><div v-if="!collapsed" class="brand-copy"><strong>蓉图云</strong><small>ADMIN CONSOLE</small></div></div>
      <div v-if="!collapsed" class="role-card" :class="auth.isGlobalAdmin ? 'global' : 'site'"><span>{{ auth.isGlobalAdmin ? 'GLOBAL ADMIN' : `SITE ${auth.user?.managed_site_id} ADMIN` }}</span><strong>{{ auth.isGlobalAdmin ? '全局管理员' : '站点管理员' }}</strong><small>{{ auth.isGlobalAdmin ? '可管理全部数据站点' : `仅管理 Site ${auth.user?.managed_site_id} 的数据` }}</small></div>
      <nav class="nav-list"><RouterLink v-for="item in navigation" :key="item.to" :to="item.to" class="nav-item" :aria-label="item.label"><el-icon><component :is="item.icon" /></el-icon><span v-if="!collapsed">{{ item.label }}</span></RouterLink></nav>
      <div class="sidebar-bottom"><div v-if="!collapsed" class="system-pill"><i :class="coordinatorOnline ? 'online' : 'offline'"></i><div><strong>{{ coordinatorOnline ? '系统运行中' : '协调节点离线' }}</strong><small>{{ auth.isGlobalAdmin ? '4 NODE CLUSTER' : `SITE ${auth.user?.managed_site_id} SCOPE` }}</small></div></div><button v-if="!collapsed" class="logout-button" @click="logout">退出 {{ auth.user?.display_name }}</button><button class="collapse-button" aria-label="折叠侧栏" @click="collapsed = !collapsed"><el-icon><Fold v-if="!collapsed" /><Expand v-else /></el-icon></button></div>
    </aside>
    <main class="main-shell"><header class="topbar"><div><div class="eyebrow">{{ route.meta.eyebrow }}</div><h1>{{ route.meta.title }}</h1></div><div class="topbar-actions"><span class="scope-badge" :class="auth.isGlobalAdmin ? 'global' : 'site'">{{ auth.isGlobalAdmin ? 'ADMIN · 全部站点' : `SITE_ADMIN · SITE ${auth.user?.managed_site_id}` }}</span><div class="clock"><span>{{ dateText }}</span><strong>{{ timeText }}</strong></div><a class="docs-button" href="http://127.0.0.1:8000/docs" target="_blank"><el-icon><Document /></el-icon><span>API 文档</span></a></div></header><section class="page-content"><RouterView /></section></main>
  </div>
</template>
<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref } from 'vue';import { RouterLink,RouterView,useRoute,useRouter } from 'vue-router';import { DataAnalysis,Document,Expand,Fold,Location,Monitor,Search,Tickets,UserFilled } from '@element-plus/icons-vue';import { getHealth } from '@/api/client';import { useAuthStore } from '@/stores/auth'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),collapsed=ref(false),now=ref(new Date()),coordinatorOnline=ref(false);let clockTimer:number|undefined,healthTimer:number|undefined
const navigation=computed(()=>[{to:'/admin',label:'管理总览',icon:DataAnalysis},{to:'/admin/resources',label:'资源管理',icon:UserFilled},{to:'/admin/map',label:'GIS 地图',icon:Location},{to:'/admin/monitor',label:'节点监控',icon:Monitor},...(auth.isGlobalAdmin?[{to:'/admin/query',label:'SQL 查询',icon:Search},{to:'/admin/schema',label:'逻辑表结构',icon:Tickets}]:[])])
const dateText=computed(()=>new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'short'}).format(now.value)),timeText=computed(()=>now.value.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}))
async function checkHealth(){try{await getHealth();coordinatorOnline.value=true}catch{coordinatorOnline.value=false}}function logout(){auth.logout();router.replace('/login')}
onMounted(()=>{checkHealth();clockTimer=window.setInterval(()=>now.value=new Date(),1000);healthTimer=window.setInterval(checkHealth,10000)});onBeforeUnmount(()=>{clearInterval(clockTimer);clearInterval(healthTimer)})
</script>
<style scoped>
.role-card{margin:24px 5px 0;padding:12px;border:1px solid rgba(41,216,199,.2);border-radius:8px;background:rgba(41,216,199,.06);display:flex;flex-direction:column}.role-card.global{border-color:rgba(169,139,255,.28);background:rgba(169,139,255,.07)}.role-card span{color:var(--cyan);font:8px 'DM Mono';letter-spacing:.12em}.role-card.global span{color:var(--purple)}.role-card strong{font-size:12px;margin-top:5px}.role-card small{color:#678198;font-size:9px;margin-top:3px}.nav-list{margin-top:18px}.scope-badge{padding:7px 10px;border:1px solid rgba(41,216,199,.25);border-radius:5px;color:var(--cyan);font:9px 'DM Mono';background:rgba(41,216,199,.07)}.scope-badge.global{color:var(--purple);border-color:rgba(169,139,255,.3);background:rgba(169,139,255,.08)}.logout-button{width:100%;padding:8px;border:1px solid var(--line);border-radius:6px;background:transparent;color:#7890a8;font-size:10px;cursor:pointer}.logout-button:hover{color:#fff;border-color:rgba(255,110,125,.35)}
</style>
